templates.settingsGradle:
pluginManagement {
	repositories {
		// Reachability mirror (same artifacts as the official maven). Listed first so builds work on
		// networks that cannot reach maven.neoforged.net; harmless when the official maven is up.
		// Reachability mirror first, then the reachable public repositories, and the official maven
		// LAST: it hard-fails with "Connection reset by peer" on some networks instead of falling
		// through, so anything listed after it is unreachable in practice.
		maven {
			name = 'NeoForgedMirror'
			url = 'https://maven.creeperhost.net'
		}
		mavenCentral()
		gradlePluginPortal()
		maven {
			name = 'NeoForged'
			url = 'https://maven.neoforged.net/releases'
		}
	}
}

// ModDevGradle resolves part of its pipeline from repositories it registers itself. Pinning dependency
// resolution to the list below keeps resolution deterministic; keep the official maven present so
// artifacts that exist only there still resolve.
dependencyResolutionManagement {
	repositoriesMode = RepositoriesMode.PREFER_SETTINGS
	repositories {
		// Reachability mirror (same content as the official maven) - harmless when the official one is up.
		maven { name = 'NeoForgedMirror'; url = 'https://maven.creeperhost.net' }
		mavenCentral()
		maven { name = 'MojangLibraries'; url = 'https://libraries.minecraft.net' }
		maven { name = 'NeoForged'; url = 'https://maven.neoforged.net/releases' }
	}
}

rootProject.name = '{{modId}}'

templates.buildGradle:
plugins {
	id 'java-library'
	id 'net.neoforged.moddev' version '{{gradle_mdgVersion}}'
}

version = project.mod_version
group = project.mod_group_id

java.toolchain.languageVersion = JavaLanguageVersion.of({{javaVersion}})

repositories {
	mavenCentral()
}

neoForge {
	version = project.neo_version

	runs {
		client {
			client()
		}
		server {
			server()
		}
	}

	mods {
		'{{modId}}' {
			sourceSet(sourceSets.main)
		}
	}
}

tasks.withType(JavaCompile).configureEach {
	options.encoding = 'UTF-8'
}

{{DATAGEN_RUN_CONFIG}}

